import os, re, html, json, hashlib, opencc

from hanrei import HANREI  # 労働裁判例データベース（日本語のみ）

BASE = os.path.dirname(os.path.abspath(__file__))

# style.css のURLに内容ハッシュを付ける。付けないと、CSSを直したときに
# 再訪者が古いCSS＋新しいHTMLの組合せになり表示が崩れる
with open(os.path.join(BASE, "style.css"), "rb") as _f:
    CSS_V = hashlib.sha1(_f.read()).hexdigest()[:8]

# 繁体字（台湾）→ 簡体字（大陸）。語彙も変換する（資訊→信息・網路→网络 等）
_CC = opencc.OpenCC("tw2sp")
_CC_PLAIN = opencc.OpenCC("t2s")  # 字体だけを変換する（語彙は変えない）
_KEEP_RE = re.compile(r'<([a-z]+)[^>]*\blang="ja"[^>]*>.*?</\1>', re.S)

# tw2sp の語彙辞書はIT用語が中心で、法律用語を別語に置き換えてしまう
# （執行→运行、程序→进程、使用者→用户、物件→对象 等）。これらは字体変換のみとする
_KEEP_WORDS = sorted((
    "執行", "程序", "使用者", "文件", "核心", "物件", "列舉", "資料", "支援",
    "線上", "文字", "整合", "複製", "檢視", "預設", "宣告",
    "連結", "簡報", "排程", "裝置", "欄位", "呼叫", "模擬", "序列", "離線",
    "入口", "宣言", "解析", "原件", "記憶", "回復", "還原", "介面",
    "型別", "紀錄", "記錄", "匯入", "匯出", "匯款", "指標", "接觸", "查詢",
    "存檔", "效能", "截圖", "通道", "撥出",
), key=len, reverse=True)

# 台湾語彙のうち、大陸では別語を使うもの（OpenCCの辞書が拾わない分を先に置換する）
_CN_WORDS = (("紀錄", "記錄"), ("影本", "複印件"), ("存取", "訪問"))

# 簡体字版は華人一般向けなので、読者への呼びかけ・読者の属性を指す語だけを「華人〜」に置き換える。
# 台湾法・台湾の制度・台湾に所在することが法的に意味を持つ記述（準拠法・戶籍謄本・台灣駕照・
# 社会保障協定・非居住者課税・ワーキングホリデー等）は事実が変わるので一切触れない
_CN_AUDIENCE = sorted((
    ("台灣人經營者", "華人經營者"), ("台灣經營者", "華人經營者"), ("台灣老闆", "華人老闆"),
    ("台灣投資者", "華人投資者"), ("台灣投資人", "華人投資人"), ("台資企業", "華人企業"),
    ("台灣房東", "華人房東"), ("台灣屋主", "華人屋主"),
    ("台灣人上班族", "華人上班族"), ("台灣朋友", "華人朋友"), ("台灣買家", "華人買家"),
), key=lambda t: len(t[0]), reverse=True)

# 日台比較が主題の記事は「台灣經營者」等が記述上の意味を持つため、呼びかけの置換から除く
CN_KEEP_TW = {"nittai-kaiko-hikaku", "shiyo-kikan-nittai"}

# 送り仮名が続く「著」は日本語の「著しく」。中国語の「放著→放着」は正しいので変換させる
_JP_RE = re.compile(r"著(?=[\u3041-\u309f])")

def to_cn(s, audience=True):
    """繁体字HTMLを簡体字に変換する。lang="ja" の要素・日本語の引用・法律用語は変換しない"""
    keep = []
    def stash(m):
        keep.append(m.group(0))
        return f"@@K{len(keep)-1}@@"
    s = _KEEP_RE.sub(stash, s)
    s = _JP_RE.sub(stash, s)
    for a, b in _CN_WORDS:
        s = s.replace(a, b)
    if audience:
        for a, b in _CN_AUDIENCE:
            s = s.replace(a, b)
    for i, w in enumerate(_KEEP_WORDS):
        s = s.replace(w, f"@@W{i}@@")
    s = _CC.convert(s)
    s = s.replace("属於", "属于")  # OpenCCが文脈により「屬於」を取りこぼすため
    s = re.sub(r"@@W(\d+)@@", lambda m: _CC_PLAIN.convert(_KEEP_WORDS[int(m.group(1))]), s)
    return re.sub(r"@@K(\d+)@@", lambda m: keep[int(m.group(1))], s)
