def ja_parts(a):
    """ja本文の冒頭<h2>【日本語版】…</h2>からタイトルを取り出し、本文と分離する"""
    m = re.match(r"\s*<h2>【日本語版】(.*?)</h2>", a["ja"])
    title = m.group(1)
    body = a["ja"][m.end():]
    return title, body

def related_block(slug, lang):
    """記事末尾の関連記事リンク（同一ディレクトリ内の相対リンク）"""
    by_slug = {a["slug"]: a for a in ARTICLES}
    items = ""
    for s in RELATED.get(slug, []):
        ra = by_slug[s]
        label_title = ra["title"] if lang == "zh" else ja_parts(ra)[0]
        items += f'<li><a href="{s}.html">{label_title}</a></li>\n'
    if not items:
        return ""
    label = "相關文章" if lang == "zh" else "関連記事"
    return f'<div class="related"><div class="label">{label}</div><ul>\n{items}</ul></div>'


FS_INIT = """<script>(function(){var v=localStorage.getItem('bsfs');if(v)document.documentElement.style.fontSize=v+'%';})();</script>"""
FS_JS = """<script>
(function(){
  var btns=document.querySelectorAll('.fontsize button');if(!btns.length)return;
  function apply(v,save){
    document.documentElement.style.fontSize=(v==='100'?'':v+'%');
    btns.forEach(function(b){b.classList.toggle('active',b.getAttribute('data-fs')===v);});
    if(save)localStorage.setItem('bsfs',v);
  }
  btns.forEach(function(b){b.addEventListener('click',function(){apply(b.getAttribute('data-fs'),true);});});
  apply(localStorage.getItem('bsfs')||'100',false);
})();
</script>"""

THEME_INIT = """<script>(function(){if(localStorage.getItem('bstheme')==='dark')document.documentElement.setAttribute('data-theme','dark');})();</script>"""
THEME_JS = """<script>
(function(){
  var b=document.querySelector('.theme-toggle');if(!b)return;
  b.addEventListener('click',function(){
    if(document.documentElement.getAttribute('data-theme')==='dark'){
      document.documentElement.removeAttribute('data-theme');localStorage.removeItem('bstheme');
    }else{
      document.documentElement.setAttribute('data-theme','dark');localStorage.setItem('bstheme','dark');
    }
  });
})();
</script>"""
TOC_JS = """<script>
(function(){
  var art=document.querySelector('article.post');if(!art)return;
  function pick(sel){return Array.prototype.filter.call(art.querySelectorAll(sel),function(h){return !h.closest('.related');});}
  var hs=pick('h2');if(hs.length<3)hs=pick('h3');if(hs.length<3)return;
  var ja=document.documentElement.lang==='ja';
  var items='';
  hs.forEach(function(h,i){if(!h.id)h.id='sec'+(i+1);items+='<li><a href="#'+h.id+'"></a></li>';});
  var toc=document.createElement('nav');toc.className='toc';
  toc.innerHTML='<div class="label">'+(ja?'目次':'目錄')+'</div><ol>'+items+'</ol>';
  var links=toc.querySelectorAll('a');
  hs.forEach(function(h,i){links[i].textContent=h.textContent;});
  var ref=art.querySelector('.tldr')||art.querySelector('.lang-note')||art.querySelector('.date');
  if(ref)ref.insertAdjacentElement('afterend',toc);
})();
</script>"""

# 言語ごとの出力先ディレクトリ・hreflang値・切替リンクのラベル
PREFIX = {"zh": "", "cn": "cn/", "ja": "ja/"}
HREFLANG = {"zh": "zh-Hant", "cn": "zh-Hans", "ja": "ja"}
SWITCH_LABEL = {"zh": "繁體", "cn": "简体", "ja": "日本語"}
ALL_LANGS = ("zh", "cn", "ja")

def lang_nav(root, base, cur, langs):
    """ヘッダーの言語切替リンク（base＝言語接頭辞を除いたパス）"""
    return "\n".join(
        f'      <a class="lang-switch" href="{root}{PREFIX[lg]}{base}" lang="{HREFLANG[lg]}">{SWITCH_LABEL[lg]}</a>'
        for lg in ALL_LANGS if lg != cur and lg in langs)

def canon(path):
    """絶対URL用のパス。Cloudflareは .html 付きURLを拡張子なしへ転送するため、
    canonical・hreflang・sitemap・構造化データはすべて拡張子なしに統一する"""
    if path.endswith("index.html"):
        return path[: -len("index.html")]
    return path[:-5] if path.endswith(".html") else path

def alt_links(base, cur, langs):
    """hreflang と canonical（絶対URL）"""
    ls = [f'<link rel="alternate" hreflang="{HREFLANG[lg]}" href="{SITE_URL}/{canon(PREFIX[lg] + base)}">'
          for lg in ALL_LANGS if lg in langs]
    # x-default は繁体字版（サイト既定）を指す。繁体字版が無いページでは出力しない
    if "zh" in langs:
        ls.append(f'<link rel="alternate" hreflang="x-default" href="{SITE_URL}/{canon(base)}">')
    ls.append(f'<link rel="canonical" href="{SITE_URL}/{canon(PREFIX[cur] + base)}">')
    return "\n".join(ls)

# 構造化データ（E-E-A-T対策）。著者＝弁護士であることを機械可読にする
PERSON_LD = {
    "@type": "Person",
    "name": "山﨑 駿",
    "alternateName": ["山崎駿", "Yamazaki Shun"],
    "jobTitle": "弁護士（Attorney at Law, Japan）",
    "url": f"{SITE_URL}/about",
    "image": f"{SITE_URL}/profile.jpg",
    "sameAs": [THREADS, YOUTUBE, INSTAGRAM, LINKEDIN],
    "memberOf": {"@type": "Organization", "name": "第一東京弁護士会"},
    "identifier": {"@type": "PropertyValue", "name": "弁護士登録番号", "value": "62384"},
    "knowsAbout": ["日本の労働法", "解雇・懲戒", "ハラスメント対応", "残業代紛争", "外国人雇用",
                   "就業規則", "労働審判", "休職・復職", "高年齢者雇用"],
    "alumniOf": {"@type": "CollegeOrUniversity", "name": "早稲田大学法学部"},
    "hasCredential": {"@type": "EducationalOccupationalCredential",
                      "credentialCategory": "司法試験予備試験合格（2018年）"},
}

def jsonld_article(a, lang, title, desc):
    url = f"{SITE_URL}/{PREFIX[lang]}articles/{a['slug']}"
    d = {
        "@context": "https://schema.org",
        "@type": "Article",
        "headline": title,
        "description": desc,
        "datePublished": a["date"],
        "inLanguage": HREFLANG[lang],
        "mainEntityOfPage": {"@type": "WebPage", "@id": url},
        "author": PERSON_LD,
    }
    return '<script type="application/ld+json">' + json.dumps(d, ensure_ascii=False) + "</script>"

def books_html(lang):
    """aboutページ用の著書・執筆リスト。lang='ja' は日本語、それ以外は繁体字（簡体字はto_cnで変換）"""
    out = []
    for b in BOOKS:
        if lang == "ja":
            name = f"『{b['title']}』" if b["kind"] == "book" else f"「{b['title']}」"
            sub = "／".join(x for x in (b["series"], b["pub"]) if x)
        else:
            name = f"《{b['title_zh']}》" if b["kind"] == "book" else f"〈{b['title_zh']}〉"
            sub = "／".join(x for x in (b["series"], b["pub_zh"]) if x)
        label = f"{name}{f'（{sub}）' if sub else ''}"
        if b["url"]:
            label = f'<a href="{b["url"]}" target="_blank" rel="noopener nofollow">{label}</a>'
        out.append(f"<li>{label}</li>")
    return "<ul>" + "".join(out) + "</ul>"

def jsonld_profile():
    # 著書・執筆を Book / Article として機械可読にし、著者が本人であることを示す
    works = []
    for b in BOOKS:
        w = {"@type": "Book" if b["kind"] == "book" else "Article",
             "name": b["title"],
             "author": {"@type": "Person", "name": "山﨑 駿"},
             "inLanguage": "ja"}
        if b["pub"]:
            w["publisher"] = {"@type": "Organization", "name": b["pub"]}
        if b["series"]:
            w["isPartOf"] = {"@type": "CreativeWork", "name": b["series"]}
        if b["url"]:
            w["url"] = b["url"]
        works.append(w)
    person = dict(PERSON_LD, subjectOf=works)
    d = {"@context": "https://schema.org", "@type": "ProfilePage", "mainEntity": person}
    return '<script type="application/ld+json">' + json.dumps(d, ensure_ascii=False) + "</script>"

def page(title, desc, body, root="", lang="zh", base="index.html", langs=ALL_LANGS, jsonld=""):
    head = {"zh": HEAD, "cn": HEAD_CN, "ja": HEAD_JA}[lang]
    foot = {"zh": FOOT, "cn": FOOT_CN, "ja": FOOT_JA}[lang]
    h = head.format(title=html.escape(title), desc=html.escape(desc), root=root,
                    langnav=lang_nav(root, base, lang, langs), threads=THREADS, youtube=YOUTUBE)
    h = h.replace("</head>", alt_links(base, lang, langs) + "\n" + jsonld + FS_INIT + THEME_INIT + "\n</head>")
    f = foot.format(root=root, threads=THREADS, youtube=YOUTUBE)
    f = f.replace("</body>", FS_JS + THEME_JS + TOC_JS + "\n</body>")
    return h + body + f

def card_zh(a):
    return f"""<a class="card catc-{CAT_SLUG[a['cat']]}" href="articles/{a['slug']}.html">
<div class="cat">{a['cat']}</div>
<h3>{a['title']}</h3>
<p>{a['summary']}</p>
<div class="date">{a['date']}</div>
</a>\n"""

def card_ja(a):
    t, _ = ja_parts(a)
    return f"""<a class="card catc-{CAT_SLUG[a['cat']]}" href="articles/{a['slug']}.html">
<div class="cat">{CAT_JA[a['cat']]}</div>
<h3>{t}</h3>
<p>{JA_SUMMARY[a['slug']]}</p>
<div class="date">{a['date']}</div>
</a>\n"""

# ===== 労働裁判例データベース（日本語のみ） =====
def hanrei_card(h):
    """一覧ページのカード。事件名・裁判所・判決日・事件番号・掲載誌・争点を
    すべてカード内に入れ、SEARCH_JS の全文絞り込みで引けるようにする"""
    return f"""<a class="card" href="hanrei/{h['slug']}.html">
<div class="cat">{h['issue']}</div>
<h3>{h['case']}</h3>
<p>{h['summary']}</p>
<div class="date">{h['court']}　{h['dateja']}　{h['docket']}／{'／'.join(h['cites'])}</div>
</a>\n"""

def hanrei_meta_table(h):
    return f"""<div class="profile">
<table>
<tr><td>事件名</td><td>{h['case']}</td></tr>
<tr><td>裁判所</td><td>{h['court']}</td></tr>
<tr><td>判決年月日</td><td>{h['dateja']}</td></tr>
<tr><td>事件番号</td><td>{h['docket']}</td></tr>
<tr><td>事件の表示</td><td>{h['cause']}</td></tr>
<tr><td>裁判結果</td><td>{h['result']}</td></tr>
<tr><td>掲載誌</td><td>{'／'.join(h['cites'])}</td></tr>
<tr><td>主な争点</td><td>{h['issue']}</td></tr>
<tr><td>関係法令</td><td>{'／'.join(h['laws'])}</td></tr>
</table>
</div>"""

def hanrei_related(h):
    """関連する解説記事へのリンク（裁判例ページ → ../articles/）"""
    by_slug = {a["slug"]: a for a in ARTICLES}
    items = ""
    for s in h.get("related", []):
        ra = by_slug.get(s)
        if not ra or not ra.get("ja"):
            continue
        items += f'<li><a href="../articles/{s}.html">{ja_parts(ra)[0]}</a></li>\n'
    if not items:
        return ""
    return f'<div class="related"><div class="label">関連する解説記事</div><ul>\n{items}</ul></div>'

def jsonld_hanrei(h):
    url = f"{SITE_URL}/ja/hanrei/{h['slug']}"
    d = {
        "@context": "https://schema.org",
        "@type": "Article",
        "headline": f"{h['case']}（{h['court']}　{h['dateja']}判決）",
        "description": h["summary"],
        "inLanguage": "ja",
        "mainEntityOfPage": {"@type": "WebPage", "@id": url},
        "author": PERSON_LD,
        "about": {"@type": "Legislation", "name": "／".join(h["laws"])},
    }
    return '<script type="application/ld+json">' + json.dumps(d, ensure_ascii=False) + "</script>"

def catnav(arts, lang, active=None):
    """カテゴリナビ（件数付き）。index・カテゴリページ共通。root直下からの相対リンク"""
    links = []
    all_label = "全部文章" if lang == "zh" else "すべての記事"
    cls = ' class="active"' if active is None else ""
    idx = "index.html#articles" if lang == "zh" else "index.html#articles"
    links.append(f'<a{cls} href="{idx}">{all_label}（{len(arts)}）</a>')
    for cat, cslug in CAT_SLUG.items():
        n = sum(1 for a in arts if a["cat"] == cat)
        label = cat if lang == "zh" else CAT_JA[cat]
        cls = ' class="active"' if active == cat else ""
        links.append(f'<a{cls} href="category-{cslug}.html">{label}（{n}）</a>')
    return '<div class="catnav">' + "\n".join(links) + "</div>"

