SEARCH_JS = """<script>
(function(){
  var q=document.getElementById('q');if(!q)return;
  var cards=Array.prototype.slice.call(document.querySelectorAll('.cards .card'));
  var empty=document.getElementById('qe');
  function filter(){
    var kw=q.value.trim().toLowerCase(),hit=0;
    cards.forEach(function(c){
      var show=!kw||c.textContent.toLowerCase().indexOf(kw)>-1;
      c.style.display=show?'':'none';if(show)hit++;
    });
    if(empty)empty.hidden=!kw||hit>0;
  }
  q.addEventListener('input',filter);
  var p=new URLSearchParams(location.search).get('q');
  if(p){
    q.value=p;filter();
    var scroll=function(){var t=document.getElementById('articles');if(t)t.scrollIntoView();};
    if(document.readyState==='complete'){scroll();}
    else{window.addEventListener('load',function(){setTimeout(scroll,0);});}
  }
})();
</script>"""

JA_SUMMARY.update({
"kigae-rodojikan": "会社が義務づけた着替え・朝礼・掃除の時間は労働時間——三菱重工長崎造船所事件（最一小判平12.3.9民集54巻3号801頁）の「指揮命令下」基準。就業規則の定め方では左右されません。毎日15分でも3年分は大きい。",
"kamin-jikan": "夜勤の仮眠時間も、警報・電話への対応義務があれば労働時間——大星ビル管理事件（最一小判平14.2.28民集56巻2号361頁）。警備・ビル管理・介護業の未払残業代リスクと宿日直許可の仕組み。",
"shucho-ido": "出張の単純な移動時間は原則労働時間に当たらない——自由利用が保障されているため。ただし物品の運搬・監視、移動中の業務指示、訪問先間の移動は労働時間。出張旅費規程の設計ポイント。",
"jizen-shonin": "残業の事前申請・承認制自体は適法だが、会社が残業を知りながら黙認すれば「黙示の指揮命令」で労働時間と認定される。申請制＋上司の制止義務＋打刻との乖離確認がセット。",
"timecard-nashi": "タイムカードがなくても残業代請求は可能——労働時間の把握義務は会社側にあり（安衛法66条の8の3）、PCログ・メール・手帳等から概括的に認定される。記録のない会社ほど訴訟で不利。",
"yukyu-kaitori": "有休の買取りは原則違法（労基法39条）。適法なのは①退職時の残日数②時効消滅分③法定を超える会社独自の有休、の3つだけ。買取りは年5日の時季指定義務の代わりになりません。",
"kyugyo-teate": "会社都合の休業には平均賃金の60%以上の休業手当が必要（労基法26条）。経営難・受注減も対象。会社に過失があれば民法536条2項で100%請求も——両者の関係はノースウエスト航空事件（最二小判昭62.7.17民集41巻5号1283頁）。",
"backpay": "解雇が無効なら、解雇期間中の賃金を全額遡及払い（民法536条2項）。他社で得た中間収入は控除できるが、平均賃金の6割までは控除不可——あけぼのタクシー事件（最一小判昭62.4.2労働判例506号20頁）。",
"chokai-futsu-kaiko": "懲戒解雇は「制裁罰」、普通解雇は「契約の解約」——要件・手続・退職金・失業保険が全部違う。解雇事由があっても苛酷にすぎる解雇は無効（高知放送事件・最二小判昭52.1.31労働判例268号17頁）。",
"yatoidome": "反復更新後の雇止めは解雇と同様に規制される——東芝柳町工場事件（最一小判昭49.7.22民集28巻5号927頁）・日立メディコ事件（最一小判昭61.12.4判例時報1221号134頁）、現在は労契法19条。更新上限は当初明示が鉄則。",
"muki-tenkan": "有期契約が通算5年を超えると無期転換申込権が発生（労契法18条）——会社は拒否できない。変わるのは契約期間だけで労働条件は従前のまま。クーリング6か月と転換逃れ雇止めのリスク。",
"seishin-rosai": "精神障害の労災申請に会社の同意は不要で、会社に「認めない」権限もありません（労災保険法施行規則23条）。会社ができるのは労基署長への意見申出（同規則23条の2）であり、支給決定自体の取消訴訟には原告適格がありません（最判令和6年7月4日・令和5年（行ヒ）第108号）。認定基準の仕組み、手続上の会社の位置、認定が出た瞬間に封じられる休職期間満了退職・解雇（労基法19条）を整理します。",
"karoshi-line": "過労死ライン＝発症前1か月100時間・2〜6か月平均80時間。電通事件（最二小判平12.3.24民集54巻3号1155頁）が確立した安全配慮義務と、36協定の絶対上限・医師面接指導など会社の予防義務。",
"tsukin-saigai": "通勤途中のケガは労災保険の通勤災害（労災保険法7条）。合理的な経路・方法での移動が要件で、逸脱・中断後は原則対象外——ただし日用品の購入・子の送迎などは経路復帰後に保護が復活。",
"chingin-tenbiki": "賃金からの一方的な天引き・相殺は労基法24条違反。従業員の同意がある相殺・賃金債権の放棄も「自由意思の客観的合理性」が必要——日新製鋼事件（最二小判平2.11.26民集44巻8号1085頁）・シンガー事件（最二小判昭48.1.19民集27巻1号27頁）。",
"sekuhara-sekinin": "セクハラは加害者本人だけでなく会社も使用者責任（民法715条）で賠償。均等法11条の防止措置義務も。管理職への厳しい懲戒は有効——L館事件（最一小判平27.2.26労働判例1109号5頁）：事前警告は処分の前提ではない。",
"kagaisha-taio": "ハラスメントの加害者と申告されたら：申告者への接触は厳禁・調査には協力しつつ反論と反証を尽くす・弁明の機会は適正手続の核心。過重な処分は労契法15条で争える。会社は双方に公正である義務を負う。",
"matahara": "妊娠を契機とする降格は原則違法・無効——広島中央保健生協事件（最一小判平26.10.23民集68巻8号1270頁）。例外は自由意思の承諾か業務上の特段の事情のみ。妊娠等から1年以内の不利益取扱いは原則「契機」と推定。",
"papa-ikukyu": "産後パパ育休＝子の出生後8週以内に最大28日・2分割可（育介法9条の2）。2025年4月の出生後休業支援給付で実質手取り約10割に。会社は拒否不可・個別周知義務あり・男性育休取得率の公表義務は300人超に拡大。",
"kaigo-kyugyo": "介護休業は対象家族1人につき通算93日・3分割可、給付67%。台湾にいる親も対象。2025年4月から介護の申出への個別周知・意向確認が会社の義務に。「介護で退職」の前に知るべき制度一覧。",
})
